28	
29	import org.springframework.http.HttpHeaders;
30	import org.springframework.http.HttpStatus;
31	import org.springframework.http.ResponseEntity;
32	import org.springframework.samples.petclinic.mapper.OwnerMapper;
33	import org.springframework.samples.petclinic.mapper.PetMapper;
34	import org.springframework.samples.petclinic.mapper.VisitMapper;
35	import org.springframework.samples.petclinic.model.Owner;
36	import org.springframework.samples.petclinic.model.Pet;
37	import org.springframework.samples.petclinic.model.Visit;
38	import org.springframework.samples.petclinic.rest.api.OwnersApi;
39	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
40	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
41	import org.springframework.samples.petclinic.rest.dto.PetDto;
42	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
43	import org.springframework.samples.petclinic.rest.dto.VisitDto;
44	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
45	import org.springframework.samples.petclinic.service.ClinicService;
46	import org.springframework.security.access.prepost.PreAuthorize;
47	import org.springframework.web.bind.annotation.CrossOrigin;
48	import org.springframework.web.bind.annotation.RequestMapping;
49	import org.springframework.web.bind.annotation.RestController;
50	import org.springframework.web.util.UriComponentsBuilder;
51	
52	import jakarta.transaction.Transactional;
53	
54	/**
55	 * @author Vitaliy Fedoriv
56	 */
57	
58	@RestController
59	@CrossOrigin(exposedHeaders = "errors, content-type")
60	@RequestMapping("/api")
61	public class OwnerRestControllerV1 implements OwnersApi {
62	
63	    /**
64	     * Pattern for a syntactically valid email address: a non-empty local part, an '@', and a
65	     * dotted domain ending in a letters-only label. Applied to the trimmed, lower-cased value.
66	     */
67	    private static final Pattern EMAIL_PATTERN =
68	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
69	
70	    /**
71	     * Common address abbreviations expanded to their full form during address normalization.
72	     * Matching is performed per whitespace-separated token on the upper-cased value.
73	     */
74	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
75	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
76	
77	    private final ClinicService clinicService;
78	
79	    private final OwnerMapper ownerMapper;
80	
81	    private final PetMapper petMapper;
82	
83	    private final VisitMapper visitMapper;
84	
85	    public OwnerRestControllerV1(ClinicService clinicService,
86	                                 OwnerMapper ownerMapper,
87	                                 PetMapper petMapper,
88	                                 VisitMapper visitMapper) {
89	        this.clinicService = clinicService;
90	        this.ownerMapper = ownerMapper;
91	        this.petMapper = petMapper;
92	        this.visitMapper = visitMapper;
93	    }
94	
95	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
96	    @Override
97	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
98	        Collection<Owner> owners;
99	        if (lastName != null) {
100	            owners = this.clinicService.findOwnerByLastName(lastName);
101	        } else {
102	            owners = this.clinicService.findAllOwners();
103	        }
104	        if (owners.isEmpty()) {
105	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
106	        }
107	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
108	    }
109	
110	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
111	    @Override
112	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
113	        Owner owner = this.clinicService.findOwnerById(ownerId);
114	        if (owner == null) {
115	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
116	        }
117	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
118	    }
119	
120	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
121	    @Override
122	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
123	        HttpHeaders headers = new HttpHeaders();
124	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
125	        String address = normalizeAddress(owner.getAddress());
126	        if (address == null || address.isEmpty()) {
127	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
128	        }
129	        owner.setAddress(address);
130	        String telephone = toE164(owner.getTelephone());
131	        if (telephone == null) {
132	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
133	        }
134	        owner.setTelephone(telephone);
135	        if (owner.getRegistrationDate() == null) {
136	            owner.setRegistrationDate(LocalDate.now());
137	        }
138	        if (owner.getEmail() != null) {
139	            String email = normalizeEmail(owner.getEmail());
140	            if (!EMAIL_PATTERN.matcher(email).matches()) {
141	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
142	            }
143	            owner.setEmail(email);
144	        }
145	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
146	            .anyMatch(existing -> telephone.equals(toE164(existing.getTelephone())));
147	        if (telephoneInUse) {
148	            return new ResponseEntity<>(HttpStatus.CONFLICT);
149	        }
150	        String lastNameKey = householdKey(owner.getLastName());
151	        String addressKey = householdKey(owner.getAddress());
152	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
153	            .filter(existing -> lastNameKey.equals(householdKey(existing.getLastName()))
154	                && addressKey.equals(householdKey(existing.getAddress())))
155	            .toList();
156	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
157	            String householdId = householdMembers.stream()
158	                .map(Owner::getHouseholdId)
159	                .filter(Objects::nonNull)
160	                .findFirst()
161	                .orElseGet(() -> householdId(owner));
162	            owner.setHouseholdId(householdId);
163	            for (Owner member : householdMembers) {
164	                if (member.getHouseholdId() == null) {
165	                    member.setHouseholdId(householdId);
166	                    this.clinicService.saveOwner(member);
167	                }
168	            }
169	        } else if (!householdMembers.isEmpty()) {
170	            return new ResponseEntity<>(HttpStatus.CONFLICT);
171	        }
172	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
173	        String firstNameKey = householdKey(owner.getFirstName());
174	        String namesakeLastNameKey = householdKey(owner.getLastName());
175	        long namesakeCount = this.clinicService.findAllOwners().stream()
176	            .filter(existing -> firstNameKey.equals(householdKey(existing.getFirstName()))
177	                && namesakeLastNameKey.equals(householdKey(existing.getLastName())))
178	            .count();
179	        owner.setNamesakeCount((int) namesakeCount);
180	        this.clinicService.saveOwner(owner);
181	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
182	        headers.setLocation(UriComponentsBuilder.newInstance()
183	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
184	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
185	    }
186	
187	    /**
188	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped.
189	     * When the value carries a leading {@code '+'} its country code is kept as given; otherwise the
190	     * Australian country code {@code '+61'} is assumed and a single leading {@code '0'} is dropped
191	     * from the national digits. The result must carry 8 to 15 digits after the {@code '+'}.
192	     *
193	     * @param telephone the raw telephone value (may be {@code null})
194	     * @return the E.164 telephone (e.g. {@code "+61412345678"}), or {@code null} if it cannot form
195	     *         a valid E.164 number
196	     */
197	    private String toE164(String telephone) {
198	        if (telephone == null) {
199	            return null;
200	        }
201	        String trimmed = telephone.trim();
202	        boolean hasCountryCode = trimmed.startsWith("+");
203	        String cleaned = trimmed.replaceAll("[\\s()\\[\\]-]", "");
204	        if (hasCountryCode) {
205	            cleaned = cleaned.substring(1);
206	        }
207	        if (!cleaned.matches("[0-9]+")) {
208	            return null;
209	        }
210	        String digits;
211	        if (hasCountryCode) {
212	            digits = cleaned;
213	        } else {
214	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
215	            digits = "61" + national;
216	        }
217	        if (digits.length() < 8 || digits.length() > 15) {
218	            return null;
219	        }
220	        return "+" + digits;
221	    }
222	
223	    /**
224	     * Normalizes an email address for storage by trimming surrounding whitespace and lower-casing
225	     * it. The result is validated by the caller against {@link #EMAIL_PATTERN}.
226	     *
227	     * @param email the raw email value (must not be {@code null})
228	     * @return the trimmed, lower-cased email
229	     */
230	    private String normalizeEmail(String email) {
231	        return email.trim().toLowerCase(Locale.ROOT);
232	    }
233	
234	    /**
235	     * Normalizes a postal address for storage and comparison: surrounding whitespace is trimmed,
236	     * internal runs of whitespace are collapsed to a single space, the value is upper-cased and
237	     * common street-type abbreviations are expanded per token ({@code ST -> STREET},
238	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). The stored and returned address is this
239	     * normalized form, and every household comparison uses it.
240	     *
241	     * @param address the raw address value (may be {@code null})
242	     * @return the normalized address, or {@code null} if the input was {@code null}
243	     */
244	    private String normalizeAddress(String address) {
245	        if (address == null) {
246	            return null;
247	        }
248	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
249	        if (collapsed.isEmpty()) {
250	            return collapsed;
251	        }
252	        String[] tokens = collapsed.split(" ");
253	        StringBuilder sb = new StringBuilder(collapsed.length());
254	        for (int i = 0; i < tokens.length; i++) {
255	            if (i > 0) {
256	                sb.append(' ');
257	            }
258	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
259	        }
260	        return sb.toString();
261	    }
262	
263	    /**
264	     * Normalizes a value for household-duplicate comparison: surrounding whitespace is trimmed,
265	     * internal runs of whitespace are collapsed to a single space and the result is lower-cased,
266	     * so that owners are compared case-insensitively with collapsed whitespace.
267	     *
268	     * @param value the raw value (must not be {@code null})
269	     * @return the normalized comparison key
270	     */
271	    private String householdKey(String value) {
272	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
273	    }
274	
275	    /**
276	     * Derives a stable, shared household identifier for the owner's household. The value is a
277	     * deterministic function of the normalized last name and address ({@link #householdKey}), so
278	     * every owner in the same household derives the identical identifier of the form
279	     * {@code 'HH-<12 upper-case hex>'}.
280	     *
281	     * @param owner the owner whose household identifier is derived
282	     * @return the stable household identifier
283	     */
284	    private String householdId(Owner owner) {
285	        String key = householdKey(owner.getLastName()) + "|" + householdKey(owner.getAddress());
286	        try {
287	            byte[] digest = MessageDigest.getInstance("SHA-256")
288	                .digest(key.getBytes(StandardCharsets.UTF_8));
289	            StringBuilder sb = new StringBuilder(digest.length * 2);
290	            for (byte b : digest) {
291	                sb.append(String.format("%02x", b));
292	            }
293	            return "HH-" + sb.substring(0, 12).toUpperCase(Locale.ROOT);
294	        }
295	        catch (java.security.NoSuchAlgorithmException e) {
296	            throw new IllegalStateException("SHA-256 not available", e);
297	        }
298	    }
299	
300	    /**
301	     * Builds the customer code for a newly registered owner in the form
302	     * {@code '<CITY3>-<LAST3>-<NNNN>'}, where {@code CITY3} is the upper-cased first three
303	     * letters of the city, {@code LAST3} the upper-cased first three letters of the last name
304	     * and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to one more than the
305	     * number of owners already registered in that city (e.g. {@code 'SYD-SMI-0007'}).
306	     *
307	     * @param city     the owner's city
308	     * @param lastName the owner's last name
309	     * @return the assigned customer code
310	     */
311	    private String nextCustomerCode(String city, String lastName) {
312	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
313	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
314	        String cityKey = householdKey(city);
315	        int sequence = (int) this.clinicService.findAllOwners().stream()
316	            .filter(existing -> existing.getCity() != null && cityKey.equals(householdKey(existing.getCity())))
317	            .count() + 1;
318	        return String.format(Locale.ROOT, "%s-%s-%04d", city3, last3, sequence);
319	    }
320	
321	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
322	    @Override
323	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
324	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
325	        if (currentOwner == null) {
326	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
327	        }
328	        String email = ownerFieldsDto.getEmail();
329	        if (email != null) {
330	            email = normalizeEmail(email);
331	            if (!EMAIL_PATTERN.matcher(email).matches()) {
332	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
333	            }
334	        }
335	        String telephone = toE164(ownerFieldsDto.getTelephone());
336	        if (telephone == null) {
337	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
338	        }
339	        currentOwner.setAddress(ownerFieldsDto.getAddress());
340	        currentOwner.setCity(ownerFieldsDto.getCity());
341	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
342	        currentOwner.setLastName(ownerFieldsDto.getLastName());
343	        currentOwner.setTelephone(telephone);
344	        currentOwner.setEmail(email);
345	        this.clinicService.saveOwner(currentOwner);
346	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
347	    }
348	
349	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
350	    @Transactional
351	    @Override
352	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
353	        Owner owner = this.clinicService.findOwnerById(ownerId);
354	        if (owner == null) {
355	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
356	        }
357	        this.clinicService.deleteOwner(owner);
358	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
359	    }
360	
361	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
362	    @Override
363	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
364	        Owner owner = this.clinicService.findOwnerById(ownerId);
365	        if (owner == null) {
366	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
367	        }
368	        HttpHeaders headers = new HttpHeaders();
369	        Pet pet = petMapper.toPet(petFieldsDto);
370	        owner.setId(ownerId);
371	        pet.setOwner(owner);
372	        pet.getType().setName(null);
373	        this.clinicService.savePet(pet);
374	        PetDto petDto = petMapper.toPetDto(pet);
375	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
376	            .buildAndExpand(pet.getId()).toUri());
377	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
378	    }
379	
380	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
381	    @Override
382	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
383	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
384	        if (currentOwner != null) {
385	            Pet currentPet = this.clinicService.findPetById(petId);
386	            if (currentPet != null) {
387	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
388	                currentPet.setName(petFieldsDto.getName());
389	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
390	                this.clinicService.savePet(currentPet);
391	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
392	            }
393	        }
394	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
395	    }
396	
397	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
398	    @Override
399	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
400	        HttpHeaders headers = new HttpHeaders();
401	        Visit visit = visitMapper.toVisit(visitFieldsDto);
402	        Pet pet = new Pet();
403	        pet.setId(petId);
404	        visit.setPet(pet);
405	        this.clinicService.saveVisit(visit);
406	        VisitDto visitDto = visitMapper.toVisitDto(visit);
407	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
408	            .buildAndExpand(visit.getId()).toUri());
409	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
410	    }
411	
412	
413	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
414	    @Override
415	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
416	        Owner owner = this.clinicService.findOwnerById(ownerId);
417	        if (owner != null) {
418	            Pet pet = owner.getPet(petId);
419	            if (pet != null) {
420	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
421	            }
422	        }
423	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
424	    }
425	}
